(function(){
  function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  function pretty(diff){
    var lines=String(diff||'').split(/\r?\n/);
    var html='';
    lines.forEach(function(l){
      var cls, txt=l;
      if(l.indexOf('+++ ')===0||l.indexOf('--- ')===0){ cls='h'; }
      else if(l.indexOf('@@')===0){ cls='h'; }
      else if(l.charAt(0)==='+'){ cls='add'; }
      else if(l.charAt(0)==='-'){ cls='del'; }
      else if(l.charAt(0)===' '){ cls='ctx'; txt=l.slice(1); }
      else { cls='ctx'; }
      html+='<div class="dl '+cls+'">'+esc(txt)+'</div>';
    });
    return {value: html};
  }
  var API={pretty:pretty, esc:esc};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__DeltaForge__=API;
})();
